with recent_inventory as (select * from inventory where store_id in (2, 5, 6) and quantity = 157), inventory_stats as (select date_trunc('MONTH', last_restock) as last_restock_month, max(quantity) - min(quantity) as quantity_range, sum(quantity) as total_quantity from recent_inventory group by date_trunc('MONTH', last_restock)) select last_restock_month, quantity_range, total_quantity from inventory_stats;
